#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    /// Integer
    I,
    /// Floating point
    F,
    /// Boolean
    B,
}

impl Kind {
    pub fn as_str(self) -> &'static str {
        match self {
            Kind::I => "i",
            Kind::F => "f",
            Kind::B => "b",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DType {
    /// NumPy-like kind category: "i", "f", or "b"
    pub kind: Kind,
    /// Element size in bytes
    pub itemsize: usize,
    /// Alignment in bytes
    pub alignment: usize,
    /// Non-empty name (e.g. "int32")
    pub name: &'static str,
    /// Signedness (true only for integer kinds in this task)
    pub signed: bool,
}

fn make_dtype(kind: Kind, itemsize: usize, alignment: usize, name: &'static str, signed: bool) -> DType {
    // Invariants required by the prompt.
    debug_assert!(!name.is_empty(), "dtype name must be non-empty");
    debug_assert!(itemsize > 0, "itemsize must be positive");
    debug_assert!(alignment > 0, "alignment must be positive");
    debug_assert!(alignment <= itemsize, "alignment must not exceed itemsize");

    // Signedness consistency: only integers are signed in this task.
    debug_assert!(
        (kind == Kind::I && signed) || (kind != Kind::I && !signed),
        "signed must be true only for integer kinds"
    );

    DType {
        kind,
        itemsize,
        alignment,
        name,
        signed,
    }
}

/// Given a NumPy-like dtype string, returns a consistent descriptor.
///
/// Assumption (per problem statement): `type_spec` is one of:
/// "int8", "int16", "int32", "int64", "float32", "float64", "bool".
pub fn numpy_dtype(type_spec: &str) -> DType {
    match type_spec {
        "int8" => make_dtype(Kind::I, 1, 1, "int8", true),
        "int16" => make_dtype(Kind::I, 2, 2, "int16", true),
        "int32" => make_dtype(Kind::I, 4, 4, "int32", true),
        "int64" => make_dtype(Kind::I, 8, 8, "int64", true),

        "float32" => make_dtype(Kind::F, 4, 4, "float32", false),
        "float64" => make_dtype(Kind::F, 8, 8, "float64", false),

        "bool" => make_dtype(Kind::B, 1, 1, "bool", false),

        // Input is guaranteed to be valid by the problem statement.
        // This arm is here to keep the function total and avoid undefined behavior.
        _ => unreachable!("invalid type_spec: {type_spec}"),
    }
}